//! Exact scalar SampleMask interface polyfill for Naga-generated Vulkan SPIR-V.
//! Applied to the final Naga-generated words in the OHOS Vulkan backend.
use std::{collections::{BTreeMap, BTreeSet}, format, string::String, vec::Vec};
#[cfg(test)]
use std::vec;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Change {
    pub variable_id: u32,
    pub storage_class: u32,
    pub scalar_type: u32,
    pub array_type: u32,
    pub accesses: usize,
}
#[derive(Debug, Clone)]
struct Plan { variable:u32, storage:u32, scalar:u32, scalar_pointer:u32, array:u32, array_pointer:u32, zero:u32, declarations:Vec<u32>, accesses:usize }

fn fresh(next:&mut u32)->Result<u32,String>{let id=*next;*next=next.checked_add(1).ok_or("SPIR-V id bound overflow")?;Ok(id)}
fn emit(out:&mut Vec<u32>,op:u16,args:&[u32]){out.push((((args.len()+1) as u32)<<16)|u32::from(op));out.extend_from_slice(args);}

/// Wrap scalar Input/Output SampleMask in an undecorated single-element array.
/// Existing array interfaces remain unchanged. Scalar loads/stores access [0]
/// with their original scalar pointer type and preserve the exact value IDs.
/// Unknown direct uses/initializers are rejected instead of guessed.
pub fn sanitize_sample_mask(words:&[u32])->Result<(Vec<u32>,Vec<Change>),String>{
    if words.len()<5||words[0]!=0x0723_0203{return Err("invalid SPIR-V header".into());}
    let mut instructions=Vec::new();let mut offset=5;let mut masks=BTreeSet::new();let mut pointers=BTreeMap::new();let mut ints=BTreeMap::new();let mut arrays=BTreeSet::new();let mut constants=BTreeMap::new();let mut variables=BTreeMap::new();
    while offset<words.len(){
        let n=(words[offset]>>16)as usize;let op=words[offset]as u16;let end=offset.checked_add(n).ok_or("instruction overflow")?;
        if n==0||end>words.len(){return Err(format!("invalid instruction at word {offset}"));}
        let w=&words[offset..end];
        let min=match op{21=>4,28=>4,29=>3,32=>4,43=>4,59=>4,61=>4,62=>3,71=>3,_=>1};
        if n<min{return Err(format!("truncated opcode {op}"));}
        match op{
            21=>{ints.insert(w[1],w[2]);}
            28|29=>{arrays.insert(w[1]);}
            32=>{pointers.insert(w[1],(w[2],w[3]));}
            43 if n==4=>{constants.insert((w[1],w[3]),(w[2],offset));}
            59=>{variables.insert(w[2],(w[1],w[3],offset,n));}
            71 if w[2]==11=>{if n!=4{return Err("malformed BuiltIn decoration".into());}if w[3]==20{masks.insert(w[1]);}}
            _=>{}
        }
        instructions.push((offset,end,op));offset=end;
    }
    let mut next=words[3];if next==0{return Err("zero SPIR-V id bound".into());}
    let mut plans=BTreeMap::new();
    for variable in masks{
        let &(pointer,storage,at,n)=variables.get(&variable).ok_or("SampleMask is not a direct variable")?;
        let &(pointer_storage,scalar)=pointers.get(&pointer).ok_or("SampleMask lacks pointer type")?;
        if arrays.contains(&scalar){continue;}
        if !matches!(storage,1|3)||pointer_storage!=storage||ints.get(&scalar)!=Some(&32){return Err("unsupported scalar SampleMask interface type/storage".into());}
        if n!=4{return Err("scalar SampleMask initializer is unsupported".into());}
        let mut declarations=Vec::new();
        let mut constant=|value:u32|->Result<u32,String>{
            if let Some(&(id,declared))=constants.get(&(scalar,value)){if declared<at{return Ok(id);}}
            let id=fresh(&mut next)?;emit(&mut declarations,43,&[scalar,id,value]);Ok(id)
        };
        let zero=constant(0)?;let one=constant(1)?;
        let array=fresh(&mut next)?;emit(&mut declarations,28,&[array,scalar,one]);
        let array_pointer=fresh(&mut next)?;emit(&mut declarations,32,&[array_pointer,storage,array]);
        plans.insert(variable,Plan{variable,storage,scalar,scalar_pointer:pointer,array,array_pointer,zero,declarations,accesses:0});
    }
    if plans.is_empty(){return Ok((words.to_vec(),Vec::new()));}
    // Accept exactly the direct interface uses generated by Naga. Scanning
    // unknown opcodes conservatively may reject a coincident literal ID; it
    // never rewrites an unrecognized pointer escape.
    for &(start,end,op) in &instructions{
        let w=&words[start..end];
        for &id in plans.keys(){
            let allowed=match op{
                5=>w.get(1)==Some(&id), // OpName target (remaining words are strings)
                15=>true, // OpEntryPoint interface list is unchanged
                59=>w.get(2)==Some(&id),
                61=>w.get(3)==Some(&id),
                62=>w.get(1)==Some(&id),
                71=>w.get(1)==Some(&id),
                _=>false,
            };
            if !allowed&&w[1..].contains(&id){return Err(format!("unsupported direct SampleMask use: opcode {op}, variable {id}"));}
        }
    }
    let mut out=words[..5].to_vec();
    for (start,end,op) in instructions{
        let w=&words[start..end];
        if op==59{
            if let Some(plan)=plans.get(&w[2]){
                out.extend_from_slice(&plan.declarations);let mut var=w.to_vec();var[1]=plan.array_pointer;out.extend_from_slice(&var);continue;
            }
        }
        let target=match op{61=>w.get(3),62=>w.get(1),_=>None}.copied();
        if let Some(plan)=target.and_then(|id|plans.get_mut(&id)){
            let ptr=fresh(&mut next)?;emit(&mut out,65,&[plan.scalar_pointer,ptr,plan.variable,plan.zero]);
            let mut access=w.to_vec();access[if op==61{3}else{1}]=ptr;out.extend_from_slice(&access);plan.accesses+=1;
        }else{out.extend_from_slice(w);}
    }
    out[3]=next;
    let report=plans.into_values().map(|p|Change{variable_id:p.variable,storage_class:p.storage,scalar_type:p.scalar,array_type:p.array,accesses:p.accesses}).collect();
    Ok((out,report))
}

#[cfg(test)]
mod tests{
 use super::*;
 fn scalar(storage:u32)->Vec<u32>{
  let mut w=vec![0x0723_0203,0x0001_0600,0,40,0];
  emit(&mut w,71,&[5,11,20]);emit(&mut w,21,&[1,32,0]);emit(&mut w,32,&[2,storage,1]);emit(&mut w,43,&[1,3,0]);emit(&mut w,43,&[1,4,1]);emit(&mut w,59,&[2,5,storage]);
  if storage==3{emit(&mut w,62,&[5,4]);}else{emit(&mut w,61,&[1,6,5]);}w
 }
 #[test]fn output_preserves_coverage_value(){let input=scalar(3);let(out,r)=sanitize_sample_mask(&input).unwrap();assert_eq!(r.len(),1);assert_eq!(r[0].accesses,1);assert_eq!(r[0].storage_class,3);assert_eq!(out[out.len()-1],4);assert_eq!(out[3],43);assert_eq!(&out[out.len()-8..out.len()-3],&[(5<<16)|65,2,42,5,3]);assert_eq!(&out[out.len()-3..],&[(3<<16)|62,42,4]);}
 #[test]fn input_preserves_load_result(){let(out,r)=sanitize_sample_mask(&scalar(1)).unwrap();assert_eq!(r[0].storage_class,1);assert_eq!(&out[out.len()-4..],&[(4<<16)|61,1,6,42]);}
 #[test]fn already_fixed_is_idempotent(){let(out,_)=sanitize_sample_mask(&scalar(3)).unwrap();let(out2,r)=sanitize_sample_mask(&out).unwrap();assert_eq!(out,out2);assert!(r.is_empty());}
 #[test]fn rejects_unknown_pointer_escape(){let mut input=scalar(3);emit(&mut input,83,&[2,7,5]);assert!(sanitize_sample_mask(&input).is_err());}
}
